/**
 * Real BFF endpoint calls for Fall Location Warning.
 */
import { apiClient } from '../api';
import { BffResponse, unwrap } from '../shared/bffEnvelope';
import type {
  FallLocationWarning,
  FallLocationWarningFilters,
  FallLocationWarningStats,
} from '../../models/FallLocationWarning';
import {
  toCreateFallLocationWarningPayload,
  toUpdateFallLocationWarningPayload,
} from './fallLocationWarningPayload';

export interface PagedResult<T> {
  items: T[];
  total: number;
  page: number;
  pageSize: number;
}

export const fallLocationWarningEndpoint = {
  getList: async (
    filters: FallLocationWarningFilters,
    page: number,
    pageSize: number,
  ): Promise<PagedResult<FallLocationWarning>> => {
    const params = new URLSearchParams({
      page:     String(page),
      pageSize: String(pageSize),
      ...(filters.search         && { search:        filters.search        }),
      ...(filters.currentStatus  && { currentStatus: filters.currentStatus }),
      ...(filters.departmentId   && { departmentId:  filters.departmentId  }),
      ...(filters.fromDate       && { fromDate:      filters.fromDate      }),
      ...(filters.toDate         && { toDate:        filters.toDate        }),
    });
    const res = await apiClient.get<BffResponse<{ items: FallLocationWarning[]; totalCount: number; page: number; pageSize: number }>>(
      `/fall-location-warnings?${params}`,
    );
    const data = unwrap(res);
    return {
      items:    data.items,
      total:    data.totalCount,
      page:     data.page,
      pageSize: data.pageSize,
    };
  },

  getStats: async (): Promise<FallLocationWarningStats> => {
    const res = await apiClient.get<BffResponse<FallLocationWarningStats>>(
      '/fall-location-warnings/stats',
    );
    return unwrap(res);
  },

  getById: async (id: string): Promise<FallLocationWarning | null> => {
    const res = await apiClient.get<BffResponse<FallLocationWarning>>(
      `/fall-location-warnings/${id}`,
    );
    return unwrap(res);
  },

  create: async (data: Partial<FallLocationWarning>): Promise<FallLocationWarning> => {
    const res = await apiClient.post<BffResponse<FallLocationWarning>>(
      '/fall-location-warnings',
      toCreateFallLocationWarningPayload(data),
    );
    return unwrap(res);
  },

  update: async (id: string, data: Partial<FallLocationWarning>): Promise<FallLocationWarning> => {
    const res = await apiClient.put<BffResponse<FallLocationWarning>>(
      `/fall-location-warnings/${id}`,
      toUpdateFallLocationWarningPayload(data),
    );
    return unwrap(res);
  },

  delete: async (id: string): Promise<void> => {
    await apiClient.delete(`/fall-location-warnings/${id}`);
  },
};
